const FAVORITES_KEY_PREFIX = 'marchesanoGymFavorites:';
function localDateKey(date) { const d = new Date(date); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function getFavoriteIds() { try { return new Set(JSON.parse(localStorage.getItem(FAVORITES_KEY_PREFIX + (currentUser?.id || 'guest')) || '[]').map(String)); } catch (_) { return new Set(); } }
function saveFavoriteIds(ids) { try { localStorage.setItem(FAVORITES_KEY_PREFIX + (currentUser?.id || 'guest'), JSON.stringify([...ids])); } catch (_) {} }
function isFavoriteExercise(item) { const ids=getFavoriteIds(); return ids.has(String(item.id || item.catalog_id || item.name)); }
function toggleFavoriteExercise(item) { const key=String(item.id || item.catalog_id || item.name); const ids=getFavoriteIds(); if(ids.has(key)) ids.delete(key); else ids.add(key); saveFavoriteIds(ids); renderExerciseCatalog(); }


// Catalogo integrato Marchesano Gym: varianti comuni per gruppo muscolare e attrezzatura.
const EXERCISE_CATALOG = [{"id":"panca-piana-bilanciere","name":"Panca piana con bilanciere","muscle_group":"Petto","equipment":"Bilanciere","instructions":"Sdraiati con piedi ben piantati, scapole raccolte e polsi in linea con gli avambracci. Abbassa il bilanciere verso la parte media del petto con controllo, poi spingi mantenendo il bacino appoggiato e senza rimbalzare.","aliases":["panca piana","bench press","bilanciere panca"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"panca-piana-manubri","name":"Panca piana con manubri","muscle_group":"Petto","equipment":"Manubri","instructions":"Appoggia i piedi a terra e stabilizza le scapole. Porta i manubri ai lati del petto con gomiti leggermente sotto la linea delle spalle, quindi spingi verso l’alto senza farli urtare. Riduci la profondità se senti fastidio alla spalla.","aliases":["panca piana manubri","dumbbell bench press"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"panca-inclinata-bilanciere","name":"Panca inclinata con bilanciere","muscle_group":"Petto","equipment":"Bilanciere","instructions":"Regola la panca su un’inclinazione moderata. Mantieni i piedi stabili e le scapole controllate; abbassa la barra verso la parte alta del petto e spingi seguendo una traiettoria fluida, senza sollevare il bacino.","aliases":["panca inclinata","incline bench press"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"panca-inclinata-manubri","name":"Panca inclinata con manubri","muscle_group":"Petto","equipment":"Manubri","instructions":"Siediti sulla panca inclinata con il busto stabile. Scendi lentamente con i manubri ai lati della parte alta del torace, mantenendo i gomiti sotto controllo; spingi senza perdere la posizione delle scapole.","aliases":["panca inclinata manubri"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"chest-press","name":"Chest press alla macchina","muscle_group":"Petto","equipment":"Macchina","instructions":"Regola sedile e impugnature affinché le mani partano all’altezza del torace. Spingi in avanti senza inarcare la schiena e ritorna lentamente finché senti un allungamento confortevole.","aliases":["chest press","macchina petto"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"croci-manubri-piana","name":"Croci con manubri su panca piana","muscle_group":"Petto","equipment":"Manubri","instructions":"Con i manubri sopra il petto, mantieni i gomiti leggermente piegati e fermi. Apri le braccia ad arco fino a un allungamento gestibile, poi riporta i manubri sopra il torace senza trasformare il gesto in una distensione.","aliases":["croci panca piana","fly manubri"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"croci-cavi","name":"Croci ai cavi","muscle_group":"Petto","equipment":"Cavi","instructions":"Posizionati al centro della stazione con un piede avanti e busto stabile. Porta le maniglie davanti al torace descrivendo un arco, mantieni una lieve flessione dei gomiti e riapri lentamente senza perdere tensione.","aliases":["croci ai cavi","cable fly"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"pec-deck","name":"Pec deck (butterfly)","muscle_group":"Petto","equipment":"Macchina","instructions":"Regola il sedile in modo che le impugnature siano all’altezza del petto. Avvicina le braccia senza sollevare le spalle, fai una breve pausa e torna indietro lentamente senza forzare l’apertura.","aliases":["butterfly","pec deck"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"push-up","name":"Piegamenti sulle braccia","muscle_group":"Petto","equipment":"Corpo libero","instructions":"Allinea testa, bacino e talloni in una linea stabile. Scendi piegando i gomiti in diagonale rispetto al busto, poi spingi il pavimento fino a distendere le braccia senza perdere la posizione del tronco.","aliases":["push up","flessioni","piegamenti"],"level":"Principiante","goal":"Forza generale","source":"marchesano"},{"id":"dip-petto","name":"Dip alle parallele (focus petto)","muscle_group":"Petto","equipment":"Parallele","instructions":"Sostieniti alle parallele, inclina leggermente il busto in avanti e controlla la discesa piegando i gomiti. Risali spingendo con fluidità; usa assistenza o riduci la profondità se le spalle non tollerano il movimento.","aliases":["dip petto","parallele"],"level":"Avanzato","goal":"Forza e massa","source":"marchesano"},{"id":"lat-machine","name":"Lat machine presa prona","muscle_group":"Schiena","equipment":"Lat machine","instructions":"Blocca le cosce sotto i cuscinetti e mantieni il busto quasi verticale. Porta la barra davanti al petto guidando i gomiti verso il basso; risali lentamente senza dondolare né tirare la barra dietro la nuca.","aliases":["lat machine","pulley alto","lat pulldown"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"trazioni-prone","name":"Trazioni alla sbarra presa prona","muscle_group":"Schiena","equipment":"Sbarra","instructions":"Afferra la sbarra poco oltre la larghezza delle spalle e parti con il corpo controllato. Porta il petto verso la sbarra guidando i gomiti in basso, poi scendi lentamente; usa elastico o macchina assistita se necessario.","aliases":["trazioni","pull up","pull-up"],"level":"Avanzato","goal":"Forza","source":"marchesano"},{"id":"rematore-bilanciere","name":"Rematore con bilanciere","muscle_group":"Schiena","equipment":"Bilanciere","instructions":"Fletti le anche e mantieni la schiena neutra, con addome attivo. Tira il bilanciere verso la parte bassa del torace senza strappare, poi distendi le braccia controllando il ritorno.","aliases":["rematore bilanciere","bent over row"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"rematore-manubrio","name":"Rematore con manubrio a un braccio","muscle_group":"Schiena","equipment":"Manubrio","instructions":"Appoggia una mano e un ginocchio sulla panca, mantenendo il busto stabile. Tira il manubrio verso il fianco senza ruotare il tronco, poi abbassalo lentamente fino a distendere il braccio.","aliases":["rematore manubrio","one arm row"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"pulley-basso","name":"Pulley basso da seduto","muscle_group":"Schiena","equipment":"Cavi","instructions":"Siediti con ginocchia leggermente flesse e busto stabile. Tira la maniglia verso l’addome portando i gomiti indietro, senza oscillare; ritorna lentamente lasciando avanzare le scapole in modo controllato.","aliases":["pulley","seated cable row"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"rematore-tbar","name":"Rematore T-bar","muscle_group":"Schiena","equipment":"T-bar","instructions":"Posiziona i piedi saldi e inclina il busto mantenendo la colonna neutra. Tira la presa verso il tronco, avvicina le scapole senza sollevare le spalle e abbassa il carico senza perdere tensione.","aliases":["t bar row","rematore t-bar"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"pulldown-braccia-tese","name":"Pulldown ai cavi a braccia tese","muscle_group":"Schiena","equipment":"Cavi","instructions":"In piedi davanti ai cavi, inclina appena il busto e mantieni i gomiti quasi fermi. Porta la barra verso le cosce usando il movimento delle spalle, poi ritorna lentamente senza inarcare la schiena.","aliases":["straight arm pulldown","braccia tese cavi"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"iperestensioni","name":"Estensioni del tronco su panca romana","muscle_group":"Schiena","equipment":"Panca romana","instructions":"Regola il supporto appena sotto le anche. Scendi flettendo il bacino e mantenendo la schiena neutra, poi risali fino ad allineare il corpo senza iperestendere la zona lombare.","aliases":["iperestensioni","back extension"],"level":"Intermedio","goal":"Controllo del tronco","source":"marchesano"},{"id":"pullover-cavo","name":"Pullover ai cavi","muscle_group":"Schiena","equipment":"Cavi","instructions":"Tieni i gomiti leggermente piegati e il busto stabile. Porta la barra dall’altezza del viso verso le cosce muovendo le spalle, poi ritorna lentamente senza trasformare l’esercizio in una spinta di tricipiti.","aliases":["pullover cavi"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"lento-avanti-manubri","name":"Spinte sopra la testa con manubri","muscle_group":"Spalle","equipment":"Manubri","instructions":"Siediti con schiena sostenuta o resta in piedi con addome contratto. Spingi i manubri sopra la testa senza inarcare la zona lombare, poi abbassali ai lati delle spalle con controllo.","aliases":["shoulder press","lento avanti manubri"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"military-press","name":"Lento avanti con bilanciere","muscle_group":"Spalle","equipment":"Bilanciere","instructions":"Tieni glutei e addome attivi, con bilanciere appoggiato davanti alle spalle. Spingi verticalmente passando con la testa sotto la barra quando supera il viso; abbassa alla posizione iniziale senza iperestendere la schiena.","aliases":["military press","overhead press"],"level":"Avanzato","goal":"Forza","source":"marchesano"},{"id":"alzate-laterali","name":"Alzate laterali con manubri","muscle_group":"Spalle","equipment":"Manubri","instructions":"Con gomiti morbidi e busto fermo, solleva i manubri lateralmente fino a circa l’altezza delle spalle. Guida con i gomiti, evita slanci e abbassa lentamente.","aliases":["lateral raise","alzate laterali"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"reverse-fly","name":"Aperture inverse per deltoidi posteriori","muscle_group":"Spalle","equipment":"Manubri","instructions":"Inclina il busto con schiena neutra e braccia sotto le spalle. Apri i manubri lateralmente stringendo dolcemente le scapole, senza slanciare il tronco; torna alla posizione iniziale lentamente.","aliases":["reverse fly","deltoidi posteriori"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"face-pull","name":"Face pull ai cavi","muscle_group":"Spalle","equipment":"Cavi","instructions":"Imposta la corda all’altezza del viso. Tira verso fronte e tempie separando le mani, con gomiti aperti e spalle lontane dalle orecchie; ritorna lentamente mantenendo il busto fermo.","aliases":["face pull","tirate al viso"],"level":"Principiante","goal":"Stabilità scapolare","source":"marchesano"},{"id":"arnold-press","name":"Arnold press con manubri","muscle_group":"Spalle","equipment":"Manubri","instructions":"Parti con i manubri davanti alle spalle e i palmi rivolti verso di te. Ruota gli avambracci mentre spingi sopra la testa, poi ripercorri il movimento senza forzare la rotazione.","aliases":["arnold press"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"alzate-frontali","name":"Alzate frontali con manubri","muscle_group":"Spalle","equipment":"Manubri","instructions":"Con busto stabile, solleva i manubri davanti al corpo fino all’altezza delle spalle. Mantieni i gomiti morbidi, evita di oscillare e scendi lentamente.","aliases":["front raise","alzate frontali"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"curl-bilanciere","name":"Curl con bilanciere","muscle_group":"Bicipiti","equipment":"Bilanciere","instructions":"In piedi, tieni i gomiti vicini ai fianchi e i polsi allineati. Fletti i gomiti sollevando la barra senza dondolare il busto, poi abbassa lentamente fino quasi a distendere le braccia.","aliases":["curl bilanciere","barbell curl"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"curl-manubri","name":"Curl alternato con manubri","muscle_group":"Bicipiti","equipment":"Manubri","instructions":"Mantieni il busto fermo e le braccia lungo i fianchi. Solleva un manubrio ruotando il palmo verso l’alto se confortevole, quindi abbassalo lentamente prima di alternare il lato.","aliases":["curl manubri","dumbbell curl"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"curl-panca-inclinata","name":"Curl con manubri su panca inclinata","muscle_group":"Bicipiti","equipment":"Manubri","instructions":"Appoggia la schiena alla panca inclinata e lascia le braccia distese ai lati. Fletti i gomiti senza spostare le spalle in avanti e torna lentamente alla posizione iniziale.","aliases":["incline curl"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"curl-martello","name":"Curl a martello","muscle_group":"Bicipiti","equipment":"Manubri","instructions":"Tieni i palmi rivolti uno verso l’altro e i gomiti vicino al busto. Solleva i manubri senza ruotare i polsi, poi abbassa in modo controllato evitando slanci.","aliases":["hammer curl","curl martello"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"curl-panca-scott","name":"Curl alla panca Scott","muscle_group":"Bicipiti","equipment":"Panca Scott","instructions":"Appoggia bene la parte posteriore delle braccia sul supporto. Fletti i gomiti senza staccare le braccia dalla panca e scendi lentamente senza bloccare bruscamente l’articolazione.","aliases":["preacher curl","panca scott"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"pushdown-corda","name":"Push-down per tricipiti con corda","muscle_group":"Tricipiti","equipment":"Cavi","instructions":"Mantieni i gomiti aderenti ai fianchi e le spalle ferme. Estendi gli avambracci verso il basso, separando leggermente le estremità della corda alla fine, poi risali senza spostare i gomiti.","aliases":["pushdown","triceps pushdown"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"french-press-manubrio","name":"Estensioni sopra la testa con manubrio","muscle_group":"Tricipiti","equipment":"Manubrio","instructions":"Sostieni il manubrio sopra la testa con gomiti rivolti in avanti. Piega i gomiti portando il carico dietro la testa entro un’ampiezza confortevole, poi estendi senza inarcare la schiena.","aliases":["french press","overhead triceps extension"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"panca-presa-stretta","name":"Panca piana presa stretta","muscle_group":"Tricipiti","equipment":"Bilanciere","instructions":"Usa una presa poco più stretta delle spalle, non eccessivamente ravvicinata. Abbassa il bilanciere mantenendo i polsi allineati e i gomiti vicini al busto, poi spingi senza rimbalzo e con assistenza se necessario.","aliases":["close grip bench press","panca stretta"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"estensioni-tricipiti-cavo","name":"Estensioni tricipiti al cavo sopra la testa","muscle_group":"Tricipiti","equipment":"Cavi","instructions":"Dai le spalle alla carrucola e porta la corda dietro la testa. Mantieni i gomiti orientati in avanti, estendi gli avambracci senza muovere il tronco e ritorna lentamente.","aliases":["overhead cable extension"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"kickback-tricipiti","name":"Kickback per tricipiti con manubrio","muscle_group":"Tricipiti","equipment":"Manubrio","instructions":"Inclina il busto mantenendo la schiena neutra e il braccio vicino al fianco. Estendi il gomito fino ad allineare l’avambraccio al braccio, poi ritorna senza oscillare la spalla.","aliases":["triceps kickback"],"level":"Intermedio","goal":"Ipertrofia","source":"marchesano"},{"id":"squat-bilanciere","name":"Squat con bilanciere","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Posiziona la barra stabile sulle spalle e crea pressione addominale prima di scendere. Piega anche e ginocchia mantenendo i piedi radicati e le ginocchia in linea con le punte; risali senza perdere l’assetto del tronco.","aliases":["back squat","squat bilanciere"],"level":"Avanzato","goal":"Forza e massa","source":"marchesano"},{"id":"front-squat","name":"Squat frontale","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Appoggia il bilanciere davanti alle spalle con gomiti alti e busto verticale. Scendi mantenendo il tronco stabile e le ginocchia in linea con i piedi, poi risali spingendo il pavimento.","aliases":["front squat"],"level":"Avanzato","goal":"Forza","source":"marchesano"},{"id":"pressa-45","name":"Pressa a 45 gradi","muscle_group":"Gambe","equipment":"Pressa","instructions":"Appoggia completamente la schiena allo schienale e posiziona i piedi alla larghezza gestibile. Sblocca la slitta, scendi senza sollevare il bacino e spingi senza bloccare bruscamente le ginocchia.","aliases":["leg press","pressa gambe"],"level":"Principiante","goal":"Forza e massa","source":"marchesano"},{"id":"leg-extension","name":"Leg extension","muscle_group":"Gambe","equipment":"Macchina","instructions":"Regola il sedile e allinea il perno della macchina al ginocchio. Estendi le gambe con controllo, fai una breve contrazione dei quadricipiti e abbassa il rullo senza lasciarlo cadere.","aliases":["leg extension","estensioni ginocchia"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"leg-curl-seduto","name":"Leg curl da seduto","muscle_group":"Gambe","equipment":"Macchina","instructions":"Allinea il ginocchio al perno e blocca il supporto sulle cosce. Fletti le ginocchia portando il rullo verso il basso, poi ritorna lentamente mantenendo il bacino aderente al sedile.","aliases":["seated leg curl"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"leg-curl-sdraiato","name":"Leg curl da sdraiato","muscle_group":"Gambe","equipment":"Macchina","instructions":"Sdraiati mantenendo il bacino stabile e allinea le ginocchia al perno. Porta il rullo verso i glutei senza sollevare le anche e abbassa lentamente fino alla posizione iniziale.","aliases":["lying leg curl"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"affondi-manubri","name":"Affondi in camminata con manubri","muscle_group":"Gambe","equipment":"Manubri","instructions":"Tieni i manubri ai lati e fai un passo abbastanza ampio. Scendi finché entrambe le ginocchia si flettono in modo controllato, mantenendo il ginocchio anteriore allineato al piede; spingi per avanzare.","aliases":["walking lunges","affondi manubri"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"bulgarian-split-squat","name":"Squat bulgaro","muscle_group":"Gambe","equipment":"Manubri","instructions":"Appoggia il piede posteriore su una panca bassa e trova una distanza stabile. Scendi in verticale mantenendo il piede anteriore ben appoggiato, poi risali spingendo attraverso tutta la pianta del piede.","aliases":["bulgarian split squat","squat bulgaro"],"level":"Avanzato","goal":"Forza e massa","source":"marchesano"},{"id":"stacco-rumeno","name":"Stacco rumeno con bilanciere","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Parti in piedi con barra vicino alle cosce. Spingi il bacino indietro con ginocchia leggermente flesse e schiena neutra, abbassa finché mantieni tensione nei femorali, poi risali estendendo le anche.","aliases":["romanian deadlift","stacco rumeno"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"stacco-convenzionale","name":"Stacco da terra convenzionale","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Avvicina la barra alle tibie, afferra saldamente e crea tensione prima di sollevare. Spingi il pavimento mantenendo la barra vicina al corpo e la schiena stabile; termina in piedi senza inclinarti all’indietro.","aliases":["deadlift","stacco da terra"],"level":"Avanzato","goal":"Powerlifting","source":"marchesano"},{"id":"stacco-trap-bar","name":"Stacco con trap bar","muscle_group":"Gambe","equipment":"Trap bar","instructions":"Centra il corpo nella trap bar, afferra le maniglie e stabilizza il tronco. Spingi attraverso il pavimento mantenendo il carico vicino al corpo, poi riappoggia flettendo anche e ginocchia in modo controllato.","aliases":["trap bar deadlift"],"level":"Intermedio","goal":"Forza generale","source":"marchesano"},{"id":"hip-thrust","name":"Hip thrust con bilanciere","muscle_group":"Glutei","equipment":"Bilanciere","instructions":"Appoggia la parte alta della schiena alla panca e posiziona il bilanciere sul bacino con protezione. Spingi attraverso i piedi fino ad allineare tronco e cosce, contraendo i glutei senza inarcare la zona lombare.","aliases":["hip thrust"],"level":"Intermedio","goal":"Forza e massa","source":"marchesano"},{"id":"glute-bridge","name":"Ponte glutei a terra","muscle_group":"Glutei","equipment":"Corpo libero","instructions":"Sdraiati con ginocchia piegate e piedi a terra. Solleva il bacino contraendo i glutei fino ad allineare anche e tronco, fai una breve pausa e scendi lentamente senza inarcare la schiena.","aliases":["glute bridge","ponte glutei"],"level":"Principiante","goal":"Attivazione e controllo","source":"marchesano"},{"id":"abduzione-anca","name":"Abduzioni dell’anca alla macchina","muscle_group":"Glutei","equipment":"Macchina","instructions":"Siediti con schiena appoggiata e ginocchia contro i cuscinetti. Apri le gambe senza slanci, mantieni brevemente la contrazione e ritorna lentamente senza far chiudere di colpo la macchina.","aliases":["abductor machine","abduzioni"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"calf-raise","name":"Calf raise in piedi","muscle_group":"Polpacci","equipment":"Macchina","instructions":"Posiziona l’avampiede sul supporto e mantieni le ginocchia distese ma non bloccate. Scendi lentamente fino a un allungamento confortevole, poi sali sulle punte senza rimbalzare.","aliases":["standing calf raise","polpacci"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"calf-raise-seduto","name":"Calf raise da seduto","muscle_group":"Polpacci","equipment":"Macchina","instructions":"Posiziona gli avampiedi sul supporto e il cuscinetto sulle cosce. Abbassa i talloni con controllo, poi spingi sulle punte e mantieni una breve contrazione in alto.","aliases":["seated calf raise"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"panca-powerlifting","name":"Panca piana stile powerlifting","muscle_group":"Petto","equipment":"Bilanciere","instructions":"Sistema piedi e scapole prima di staccare la barra dai supporti. Mantieni i glutei sulla panca, porta la barra al punto di contatto scelto sul torace con controllo e spingi seguendo una traiettoria stabile. Allenati con spotter e sicurezze regolate.","aliases":["powerlifting bench","panca gara"],"level":"Avanzato","goal":"Powerlifting","source":"marchesano"},{"id":"squat-powerlifting","name":"Squat stile powerlifting","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Regola la posizione della barra e crea pressione addominale prima di iniziare. Scendi mantenendo equilibrio sul piede e controllo del busto, raggiungi una profondità ripetibile e risali senza perdere la traiettoria. Usa rack con sicurezze.","aliases":["powerlifting squat","squat gara"],"level":"Avanzato","goal":"Powerlifting","source":"marchesano"},{"id":"stacco-sumo","name":"Stacco sumo","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Imposta una stance ampia e afferra la barra all’interno delle gambe. Spingi le ginocchia verso la direzione delle punte e crea tensione prima del distacco; solleva mantenendo la barra vicina e chiudi in posizione eretta.","aliases":["sumo deadlift","stacco sumo"],"level":"Avanzato","goal":"Powerlifting","source":"marchesano"},{"id":"pausa-panca","name":"Panca piana con pausa al petto","muscle_group":"Petto","equipment":"Bilanciere","instructions":"Esegui la discesa come una panca controllata, fermando la barra immobile sul torace senza rilassare le spalle. Dopo la pausa, spingi in modo deciso mantenendo piedi, scapole e bacino stabili.","aliases":["paused bench press","panca con pausa"],"level":"Avanzato","goal":"Forza massimale","source":"marchesano"},{"id":"squat-pausa","name":"Squat con pausa","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Scendi con il tuo assetto abituale e fermati nella posizione bassa senza rimbalzare. Mantieni tensione nell’addome e nei piedi durante la pausa, poi risali conservando la traiettoria.","aliases":["pause squat"],"level":"Avanzato","goal":"Forza tecnica","source":"marchesano"},{"id":"stacco-pausa","name":"Stacco con pausa sotto il ginocchio","muscle_group":"Gambe","equipment":"Bilanciere","instructions":"Imposta lo stacco con barra vicina alle tibie e schiena stabile. Solleva fino a poco sotto il ginocchio, fai una pausa mantenendo tensione e poi completa la salita senza allontanare la barra dal corpo.","aliases":["paused deadlift"],"level":"Avanzato","goal":"Forza tecnica","source":"marchesano"},{"id":"panca-multipower","name":"Panca piana al multipower","muscle_group":"Petto","equipment":"Multipower","instructions":"Regola la panca sotto la barra e verifica che i fermi siano accessibili. Mantieni piedi e scapole stabili, abbassa fino a un punto confortevole sul petto e spingi senza rimbalzo.","aliases":["smith machine bench press","panca smith"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"squat-multipower","name":"Squat al multipower","muscle_group":"Gambe","equipment":"Multipower","instructions":"Posiziona i piedi in modo da trovare una traiettoria naturale sotto la barra. Scendi piegando anche e ginocchia con controllo, mantieni il bacino stabile e risali senza bloccare bruscamente le ginocchia.","aliases":["smith squat","squat smith"],"level":"Principiante","goal":"Ipertrofia","source":"marchesano"},{"id":"plank","name":"Plank frontale","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Appoggia avambracci e punte dei piedi, mantenendo gomiti sotto le spalle. Contrai addome e glutei e allinea testa, bacino e talloni; interrompi la tenuta quando la zona lombare inizia a cedere.","aliases":["plank"],"level":"Principiante","goal":"Stabilità del tronco","source":"marchesano"},{"id":"crunch","name":"Crunch a terra","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Sdraiati con ginocchia piegate e mani leggere ai lati della testa o sul petto. Solleva le scapole avvicinando le costole al bacino, espira durante la salita e torna lentamente senza tirare il collo.","aliases":["crunch addominali"],"level":"Principiante","goal":"Controllo addominale","source":"marchesano"},{"id":"sollevamento-gambe","name":"Sollevamento gambe da sdraiato","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Sdraiati e stabilizza la zona lombare contro il pavimento. Solleva le gambe senza slancio e abbassale solo fin dove riesci a mantenere il bacino controllato; piega le ginocchia per semplificare.","aliases":["leg raise"],"level":"Intermedio","goal":"Controllo addominale","source":"marchesano"},{"id":"dead-bug","name":"Dead bug","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Sdraiati con braccia verso l’alto e anche e ginocchia a 90 gradi. Allunga lentamente braccio e gamba opposti mantenendo la zona lombare stabile, poi alterna senza accelerare.","aliases":["dead bug"],"level":"Principiante","goal":"Stabilità del tronco","source":"marchesano"},{"id":"pallof-press","name":"Pallof press ai cavi","muscle_group":"Addome","equipment":"Cavi","instructions":"Posizionati di lato rispetto alla carrucola e porta la maniglia al petto. Estendi le braccia davanti a te senza ruotare il busto, mantieni la posizione e ritorna controllando la trazione laterale.","aliases":["pallof press"],"level":"Principiante","goal":"Anti-rotazione","source":"marchesano"},{"id":"ab-wheel","name":"Ruota addominale","muscle_group":"Addome","equipment":"Ruota addominale","instructions":"Parti in ginocchio con addome contratto e bacino controllato. Fai scorrere la ruota in avanti solo finché riesci a evitare l’inarcamento lombare, poi torna indietro usando il tronco e non uno strappo delle braccia.","aliases":["ab wheel","rollout"],"level":"Avanzato","goal":"Stabilità del tronco","source":"marchesano"},{"id":"side-plank","name":"Plank laterale","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Appoggia l’avambraccio sotto la spalla e impila i piedi o piega le ginocchia per facilitare. Solleva il bacino mantenendo il corpo allineato e respira regolarmente senza ruotare il torace.","aliases":["side plank"],"level":"Principiante","goal":"Stabilità laterale","source":"marchesano"},{"id":"reverse-crunch","name":"Crunch inverso","muscle_group":"Addome","equipment":"Corpo libero","instructions":"Sdraiati con ginocchia piegate e addome attivo. Avvicina il bacino al torace sollevando leggermente il sacro, senza slanciare le gambe; torna a terra lentamente.","aliases":["reverse crunch"],"level":"Intermedio","goal":"Controllo addominale","source":"marchesano"}];

